<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/security.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/portal.php';
requireRole(['Admin']);$sch=$pdo->query('SELECT s.id,s.student_number,u.full_name FROM scholars s JOIN users u ON u.id=s.user_id ORDER BY u.full_name')->fetchAll();$q=$pdo->query('SELECT u.full_name,s.student_number,g.term,g.average,g.created_at FROM grade_records g JOIN scholars s ON s.id=g.scholar_id JOIN users u ON u.id=s.user_id ORDER BY g.created_at DESC');$rows=[];foreach($q->fetchAll() as $r)$rows[]=[h($r['full_name']),h($r['student_number']),h($r['term']),h($r['average']),h($r['created_at'])];portalStart('Academic Records','grades.php');echo '<div class="portal-panel"><h2>Record grade</h2><form class="portal-form" method="post" action="../portal_action.php">'.csrf_field().'<input type="hidden" name="action" value="record_grade"><input type="hidden" name="back" value="grades.php"><label>Scholar<select name="scholar_id">';foreach($sch as $s)echo '<option value="'.h($s['id']).'">'.h($s['full_name'].' '.$s['student_number']).'</option>';echo '</select></label><label>Term<input name="term" required maxlength="30"></label><label>Average<input type="number" name="average" min="0" max="100" step=".01" required></label><button class="portal-button">Save grade</button></form></div>';portalTable(['Scholar','Number','Term','Average','Recorded'],$rows);portalEnd();